INSERT INTO quiz_questions (module_id, question_order, question_text)
SELECT m.id, 1, CONCAT('Яка основна мета модуля "', m.title, '"?') FROM modules m;
INSERT INTO quiz_questions (module_id, question_order, question_text)
SELECT m.id, 2, 'Що потрібно зробити перед переходом до наступного модуля?' FROM modules m;
INSERT INTO quiz_questions (module_id, question_order, question_text)
SELECT m.id, 3, 'Хто відкриває доступ до програми після подання заявки?' FROM modules m;

INSERT INTO quiz_options (question_id, option_order, option_text, is_correct)
SELECT q.id, 1, 'Опанування теми та перевірка знань', 1 FROM quiz_questions q WHERE q.question_order = 1;
